@prefix osc: <https://w3id.org/ogc/stac/osc/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://ogc.org/demo/ospd/polarwarp> ;
            sh:resultMessage "Value does not have class skos:Concept" ;
            sh:resultPath osc:status ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:ClassConstraintComponent ;
            sh:sourceShape [ sh:class skos:Concept ;
                    sh:in ( osc:planned osc:ongoing osc:completed ) ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path osc:status ] ;
            sh:value osc:completed ],
        [ a sh:ValidationResult ;
            sh:focusNode <https://ogc.org/demo/ospd/polarwarp> ;
            sh:resultMessage "Value does not have class skos:Concept" ;
            sh:resultPath osc:type ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraintComponent sh:ClassConstraintComponent ;
            sh:sourceShape [ sh:class skos:Concept ;
                    sh:in ( osc:project-type osc:product-type ) ;
                    sh:maxCount 1 ;
                    sh:minCount 1 ;
                    sh:path osc:type ] ;
            sh:value osc:product-type ] .
